import typer
import click

app = typer.Typer()

# In 0.25.1, users could customize Click field types
class CustomClickType(click.ParamType):
    name = "custom"

    def convert(self, value, param, ctx):
        return value.upper()

@app.command()
def greet(name: str = typer.Option(..., click_type=CustomClickType())):
    print(name)
